/* 星脉 · 服务关系图谱 — 深色主题 */
:root {
  --bg: #0a0e13;
  --bg-2: #0d1218;
  --panel: #0f141b;
  --panel-2: #131a23;
  --border: #1c2530;
  --border-2: #26313f;
  --text: #d7dee8;
  --muted: #7c8a9c;
  --faint: #55647a;
  --dep: #4da3ff;
  --imp: #ff8c42;
  --trail: #ffc857;
  --p0: #ff5d5d;
  --p1: #ffb020;
  --p2: #6b7a8c;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100%; }
body {
  font-family: "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  background: var(--bg);
  color: var(--text);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  font-size: 13px;
}
.hidden { display: none !important; }
button { font-family: inherit; }

/* ---------- 顶栏 ---------- */
#topbar {
  display: flex; align-items: center; gap: 18px;
  height: 58px; padding: 0 18px;
  background: linear-gradient(180deg, #10161f, #0c1118);
  border-bottom: 1px solid var(--border);
  flex: none;
}
.brand { display: flex; align-items: center; gap: 10px; }
.brand-dot {
  width: 26px; height: 26px; border-radius: 8px; flex: none;
  background: conic-gradient(from 210deg, #4da3ff, #b48cf2, #ff8c42, #2fbf9b, #4da3ff);
  box-shadow: 0 0 12px rgba(77, 163, 255, .45);
  position: relative;
}
.brand-dot::after {
  content: ""; position: absolute; inset: 8px; border-radius: 50%;
  background: #0c1118;
}
.brand-text h1 { font-size: 15px; font-weight: 600; letter-spacing: .5px; }
.brand-text p { font-size: 10.5px; color: var(--muted); letter-spacing: 1.5px; margin-top: 1px; }

.search-wrap { position: relative; margin-left: 8px; }
.search-ico { position: absolute; left: 10px; top: 50%; transform: translateY(-50%); color: var(--faint); pointer-events: none; }
#search {
  width: 250px; height: 32px; padding: 0 12px 0 30px;
  background: var(--bg-2); border: 1px solid var(--border-2); border-radius: 8px;
  color: var(--text); font-size: 12.5px; outline: none;
  transition: border-color .15s, box-shadow .15s;
}
#search:focus { border-color: #3b5a7d; box-shadow: 0 0 0 3px rgba(77, 163, 255, .12); }
#search-drop {
  position: absolute; top: 37px; left: 0; width: 290px; z-index: 60;
  background: var(--panel-2); border: 1px solid var(--border-2); border-radius: 10px;
  box-shadow: 0 12px 32px rgba(0, 0, 0, .5); overflow: hidden; padding: 4px;
}
.search-item {
  display: flex; align-items: center; gap: 8px;
  padding: 7px 9px; border-radius: 7px; cursor: pointer; font-size: 12.5px;
}
.search-item:hover, .search-item.hot { background: #1b2532; }
.search-item .dot { width: 8px; height: 8px; border-radius: 50%; flex: none; }
.search-item .sid { color: var(--faint); font-size: 11px; margin-left: auto; font-family: Consolas, monospace; }
.search-empty { padding: 10px; color: var(--muted); font-size: 12px; }

.global-stats { margin-left: auto; display: flex; gap: 14px; color: var(--muted); font-size: 12px; white-space: nowrap; }
.global-stats b { color: var(--text); font-weight: 600; }

/* ---------- 面包屑 / 跟随路径 ---------- */
#crumbbar {
  display: flex; align-items: center; gap: 10px;
  min-height: 38px; padding: 4px 18px;
  background: #0c1119; border-bottom: 1px solid var(--border);
  flex: none; flex-wrap: wrap;
}
.crumb-label {
  display: inline-flex; align-items: center; gap: 5px;
  color: var(--trail); font-size: 11.5px; letter-spacing: 1px; flex: none;
}
#crumbs { display: flex; align-items: center; flex-wrap: wrap; list-style: none; gap: 2px; }
.crumb {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 3px 10px; border-radius: 999px;
  background: #151d28; border: 1px solid var(--border-2);
  font-size: 12px; cursor: pointer; color: #b9c4d2;
  transition: border-color .15s, color .15s;
}
.crumb:hover { border-color: var(--trail); color: var(--text); }
.crumb.current {
  border-color: rgba(255, 200, 87, .55); color: var(--trail);
  background: rgba(255, 200, 87, .08); font-weight: 600; cursor: default;
}
.crumb-sep { color: var(--faint); padding: 0 3px; }
.crumb-type { width: 7px; height: 7px; border-radius: 50%; flex: none; }
#crumb-reset {
  background: none; border: 1px solid var(--border-2); color: var(--muted);
  border-radius: 6px; padding: 3px 10px; font-size: 11.5px; cursor: pointer;
}
#crumb-reset:hover { color: var(--text); border-color: var(--faint); }
.crumb-hint { color: var(--faint); font-size: 11px; margin-left: auto; }

/* ---------- 主区 ---------- */
main { flex: 1; display: flex; min-height: 0; }
#canvas-wrap { flex: 1; position: relative; min-width: 0; background:
  radial-gradient(1200px 700px at 50% 40%, #0d1420 0%, var(--bg) 68%); }
#graph { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }

/* ---------- 图元 ---------- */
.edge { stroke-width: 1.4; fill: none; opacity: .38; transition: opacity .25s, stroke-width .2s; }
.edge.lit { opacity: .95; stroke-width: 2; filter: brightness(1.25); }
.edge.dim { opacity: .05; }
.edge.trail {
  stroke: var(--trail) !important; stroke-width: 2.4; opacity: 1;
  stroke-dasharray: 7 5; animation: trailflow 1.1s linear infinite;
  filter: drop-shadow(0 0 3px rgba(255, 200, 87, .5));
}
@keyframes trailflow { to { stroke-dashoffset: -24; } }

.node { cursor: pointer; transition: opacity .3s; }
.node.dim { opacity: .13; }
.node.off { opacity: .04; pointer-events: none; }
.node .main { transition: stroke .2s, stroke-width .2s, fill-opacity .2s; }
.node .label {
  font-size: 12px; fill: #a7b3c2; text-anchor: middle;
  paint-order: stroke; stroke: #0a0e13; stroke-width: 3.5px;
  pointer-events: none; transition: fill .2s;
}
.node:hover .main { stroke-width: 3; }
.node:hover .label { fill: #e6ecf4; }
.node.dep .label { fill: #bcd9ff; }
.node.imp .label { fill: #ffd4b3; }
.node.focus .label { fill: #ffffff; font-weight: 600; }
.node.focus .main { stroke: #fff; stroke-width: 2.6; }
.node .halo { fill: none; stroke-width: 2; opacity: 0; transition: opacity .35s; pointer-events: none; }
.node .halo-dep { stroke: var(--dep); stroke-dasharray: 4 4; }
.node .halo-imp { stroke: var(--imp); stroke-dasharray: 1.5 4.5; stroke-linecap: round; }
.node .focusring { fill: none; stroke: #fff; stroke-width: 1.4; opacity: 0; transition: opacity .3s; pointer-events: none; }
.node.focus .focusring { opacity: .9; animation: breathe 2.2s ease-in-out infinite; }
@keyframes breathe { 50% { opacity: .35; } }

/* ---------- 角标 / 图例 ---------- */
#mode-badge {
  position: absolute; right: 14px; bottom: 12px; z-index: 10;
  display: flex; align-items: center; gap: 7px;
  padding: 5px 12px; border-radius: 999px;
  background: rgba(15, 21, 30, .82); border: 1px solid var(--border-2);
  color: var(--muted); font-size: 11px; letter-spacing: .5px;
  backdrop-filter: blur(4px);
}
.pulse-dot { width: 7px; height: 7px; border-radius: 50%; background: #2fbf9b; box-shadow: 0 0 6px #2fbf9b; }

#legend {
  position: absolute; left: 14px; bottom: 12px; z-index: 10;
  padding: 11px 13px; border-radius: 12px;
  background: rgba(15, 21, 30, .85); border: 1px solid var(--border-2);
  backdrop-filter: blur(4px); max-width: 330px;
}
.legend-title { font-size: 10.5px; color: var(--faint); margin: 4px 0 6px; letter-spacing: .5px; }
.legend-title:first-child { margin-top: 0; }
.legend-row { display: flex; flex-wrap: wrap; gap: 5px; }
.lg-type {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 2.5px 9px; border-radius: 999px; font-size: 11px;
  background: #141c26; border: 1px solid var(--border-2); color: #b9c4d2; cursor: pointer;
  transition: opacity .15s, border-color .15s;
}
.lg-type .dot { width: 7px; height: 7px; border-radius: 50%; }
.lg-type .cnt { color: var(--faint); }
.lg-type.off { opacity: .35; border-style: dashed; }
.legend-kinds { display: flex; flex-wrap: wrap; gap: 5px 13px; font-size: 11px; color: #9fabb9; }
.legend-kinds .lk { display: inline-block; width: 14px; height: 3px; border-radius: 2px; margin-right: 5px; vertical-align: middle; }
.p0-toggle { display: inline-flex; align-items: center; gap: 6px; margin-top: 9px; font-size: 11.5px; color: #9fabb9; cursor: pointer; user-select: none; }
.p0-toggle input { accent-color: var(--p0); cursor: pointer; }

/* ---------- Tooltip ---------- */
#tooltip {
  position: absolute; z-index: 40; pointer-events: none;
  max-width: 250px; padding: 9px 11px; border-radius: 10px;
  background: rgba(17, 24, 34, .96); border: 1px solid var(--border-2);
  box-shadow: 0 10px 26px rgba(0, 0, 0, .5); font-size: 12px; line-height: 1.55;
}
#tooltip .tt-name { font-weight: 600; font-size: 13px; display: flex; align-items: center; gap: 7px; }
#tooltip .tt-meta { color: var(--muted); margin-top: 2px; }
#tooltip .tt-desc { color: #9fabb9; margin-top: 3px; }
#tooltip .tt-go { color: var(--trail); margin-top: 4px; font-size: 11px; }
#tooltip .crit { margin-left: 0; }

/* ---------- 右侧面板 ---------- */
#panel {
  width: 336px; flex: none; overflow-y: auto;
  background: var(--panel); border-left: 1px solid var(--border);
  padding: 16px 16px 26px; scrollbar-width: thin; scrollbar-color: #2a3646 transparent;
}
#panel::-webkit-scrollbar { width: 8px; }
#panel::-webkit-scrollbar-thumb { background: #2a3646; border-radius: 4px; }

.p-empty { color: var(--muted); font-size: 12.5px; line-height: 2; padding-top: 30px; text-align: center; }
.p-empty .big { font-size: 30px; display: block; margin-bottom: 8px; opacity: .5; }

.p-head h2 { font-size: 17px; font-weight: 650; margin-top: 8px; display: flex; align-items: center; gap: 8px; }
.type-badge {
  font-size: 10.5px; padding: 2px 8px; border-radius: 999px; font-weight: 500; flex: none;
  color: var(--c); background: color-mix(in srgb, var(--c) 14%, transparent);
  border: 1px solid color-mix(in srgb, var(--c) 45%, transparent);
}
.crit {
  display: inline-flex; align-items: center; font-size: 10.5px; font-weight: 700;
  padding: 1px 7px; border-radius: 5px; flex: none;
}
.crit::before { content: ""; width: 5px; height: 5px; border-radius: 50%; margin-right: 4px; background: currentColor; }
.crit.P0 { color: var(--p0); background: rgba(255, 93, 93, .12); }
.crit.P1 { color: var(--p1); background: rgba(255, 176, 32, .12); }
.crit.P2 { color: #8d9cad; background: rgba(107, 122, 140, .16); }
.p-meta { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; color: var(--muted); font-size: 11.5px; margin-top: 7px; }
.p-meta .sid { font-family: Consolas, monospace; color: var(--faint); }
.p-desc { color: #9fabb9; font-size: 12px; line-height: 1.7; margin-top: 8px; }

.p-narrative {
  margin-top: 12px; padding: 10px 12px; border-radius: 10px; font-size: 12px; line-height: 1.75;
  background: linear-gradient(135deg, rgba(77, 163, 255, .07), rgba(255, 140, 66, .07));
  border: 1px solid rgba(120, 150, 190, .18); color: #c3cedd;
}
.p-narrative b { color: var(--text); }
.p-narrative .n-dep { color: var(--dep); font-weight: 600; }
.p-narrative .n-imp { color: var(--imp); font-weight: 600; }

.p-radius { display: flex; align-items: center; gap: 10px; margin-top: 14px; }
.p-radius > span { font-size: 11.5px; color: var(--muted); flex: none; }
.seg { display: flex; background: var(--bg-2); border: 1px solid var(--border-2); border-radius: 8px; padding: 2px; gap: 2px; }
.seg button {
  border: none; background: none; color: var(--muted); font-size: 11.5px;
  padding: 4px 10px; border-radius: 6px; cursor: pointer; transition: all .15s;
}
.seg button:hover { color: var(--text); }
.seg button.on { background: #243245; color: #fff; font-weight: 600; }

.p-stats { display: flex; gap: 8px; margin-top: 12px; }
.stat-card {
  flex: 1; padding: 9px 11px; border-radius: 10px;
  background: var(--panel-2); border: 1px solid var(--border);
}
.stat-card .num { font-size: 19px; font-weight: 700; line-height: 1.2; }
.stat-card .lab { font-size: 10.5px; color: var(--muted); margin-top: 2px; }
.stat-card.imp .num { color: var(--imp); }
.stat-card.dep .num { color: var(--dep); }
.stat-card .sub { font-size: 10px; color: var(--faint); margin-top: 2px; }

.p-sec { margin-top: 18px; }
.p-sec > h3 {
  display: flex; align-items: baseline; gap: 7px; font-size: 13px; font-weight: 650; margin-bottom: 8px;
}
.p-sec > h3 .tag { width: 8px; height: 8px; border-radius: 50%; align-self: center; }
.p-sec > h3 .cnt { color: var(--faint); font-weight: 400; font-size: 11px; }
.p-sec > h3 .kinds { color: var(--faint); font-weight: 400; font-size: 10.5px; margin-left: auto; }

.rel-group { font-size: 10.5px; color: var(--faint); margin: 8px 0 4px; display: flex; align-items: center; gap: 6px; }
.rel-group::after { content: ""; flex: 1; height: 1px; background: var(--border); }
.rel-item {
  display: flex; align-items: center; gap: 8px; width: 100%;
  padding: 6.5px 9px; margin-bottom: 2px;
  background: none; border: 1px solid transparent; border-radius: 8px;
  color: var(--text); font-size: 12.5px; text-align: left; cursor: pointer;
  transition: background .13s, border-color .13s;
}
.rel-item:hover { background: #16202c; border-color: var(--border-2); }
.rel-item:hover .rel-go { opacity: 1; transform: translateX(2px); }
.rel-item .dot { width: 8px; height: 8px; border-radius: 50%; flex: none; }
.rel-item .rel-name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rel-item .crit { padding: 0 5px; font-size: 9.5px; }
.rel-kind { font-size: 9.5px; padding: 1px 6px; border-radius: 4px; flex: none; color: #9db2cc; background: #182130; }
.rel-go { color: var(--trail); opacity: 0; transition: all .15s; flex: none; font-weight: 700; }
.rel-none { color: var(--faint); font-size: 11.5px; padding: 6px 9px; }
.depth-chip { font-size: 9.5px; color: #8fa0b5; border: 1px solid var(--border-2); padding: 0.5px 5px; border-radius: 4px; flex: none; }

@media (max-width: 1080px) { #panel { width: 290px; } }

