1	// 星脉 · 服务关系图谱 — 布局 / 渲染 / 交互（无框架、零外部依赖）
2	(function () {
3	  'use strict';
4	
5	  // 初始化错误显式上报（避免白屏静默失败）
6	  window.addEventListener('error', function (ev) {
7	    var d = document.createElement('div');
8	    d.id = 'app-error';
9	    d.textContent = 'JS错误: ' + ev.message + ' @line ' + ev.lineno;
10	    d.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:999;background:#7a1f1f;color:#fff;padding:4px 10px;font:12px monospace';
11	    document.body.appendChild(d);
12	  });
13	
14	  var G = window.GRAPH;
15	  var nodes = G.nodes;
16	  var edges = G.edges;
17	  var byId = {};
18	  nodes.forEach(function (n) { byId[n.id] = n; });
19	
20	  var TYPE_META = {
21	    service:  { label: '服务',   color: '#5aa2ff' },
22	    data:     { label: '数据',   color: '#2fbf9b' },
23	    queue:    { label: '消息',   color: '#b48cf2' },
24	    external: { label: '外部',   color: '#f0b429' },
25	    client:   { label: '客户端', color: '#e8688a' }
26	  };
27	  var KIND_META = {
28	    call: { label: '同步调用', tag: '调用', marker: 'm-call', color: '#4d6f96', dash: null },
29	    data: { label: '数据读写', tag: '读写', marker: 'm-data', color: '#2f8577', dash: null },
30	    pub:  { label: '发布事件', tag: '发布', marker: 'm-event', color: '#8d6fd6', dash: '6 3' },
31	    sub:  { label: '订阅事件', tag: '订阅', marker: 'm-event', color: '#8d6fd6', dash: '2 4' }
32	  };
33	  var DEP_COLOR = '#4da3ff';
34	  var IMP_COLOR = '#ff8c42';
35	
36	  /* ================= 邻接与统计 ================= */
37	  // 语义：边 A→B = A 依赖 B；影响沿反向传播。pub（发布事件）为相互影响。
38	  var outAdj = new Map();  // a -> [b, ...]   a 依赖谁
39	  var inAdj = new Map();   // b -> [a, ...]   谁依赖 b（即 b 的影响对象）
40	  function pushAdj(m, a, b) {
41	    if (!m.has(a)) m.set(a, []);
42	    m.get(a).push(b);
43	  }
44	  var deg = {};
45	  edges.forEach(function (e) {
46	    pushAdj(outAdj, e.s, e.t);
47	    pushAdj(inAdj, e.t, e.s);
48	    if (e.kind === 'pub') { // 双向
49	      pushAdj(outAdj, e.t, e.s);
50	      pushAdj(inAdj, e.s, e.t);
51	    }
52	    deg[e.s] = (deg[e.s] || 0) + 1;
53	    deg[e.t] = (deg[e.t] || 0) + 1;
54	  });
55	
56	  function bfsDepth(start, adj) {
57	    var depth = new Map([[start, 0]]);
58	    var q = [start];
59	    while (q.length) {
60	      var cur = q.shift();
61	      var d = depth.get(cur);
62	      var nx = adj.get(cur) || [];
63	      for (var i = 0; i < nx.length; i++) {
64	        if (!depth.has(nx[i])) { depth.set(nx[i], d + 1); q.push(nx[i]); }
65	      }
66	    }
67	    return depth;
68	  }
69	
70	  /* ================= 确定性力导向布局 ================= */
71	  function mulberry32(seed) {
72	    return function () {
73	      seed |= 0; seed = seed + 0x6D2B79F5 | 0;
74	      var t = Math.imul(seed ^ seed >>> 15, 1 | seed);
75	      t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
76	      return ((t ^ t >>> 14) >>> 0) / 4294967296;
77	    };
78	  }
79	  // 类型簇中心（手排五角位，保证簇间分离、图面可读）
80	  var CLUSTER = {
81	    client:   [-460, -270],
82	    service:  [0, 0],
83	    queue:    [370, -230],
84	    data:     [380, 250],
85	    external: [-360, 280]
86	  };
87	  function computeLayout() {
88	    var rng = mulberry32(20260908);
89	    var pos = {};
90	    nodes.forEach(function (n) {
91	      var c = CLUSTER[n.type];
92	      pos[n.id] = { x: c[0] + (rng() - 0.5) * 300, y: c[1] + (rng() - 0.5) * 300, vx: 0, vy: 0 };
93	    });
94	    var ITER = 340;
95	    for (var it = 0; it < ITER; it++) {
96	      var i, j, a, b, dx, dy, d2, d, f;
97	      // 斥力
98	      for (i = 0; i < nodes.length; i++) {
99	        for (j = i + 1; j < nodes.length; j++) {
100	          a = pos[nodes[i].id]; b = pos[nodes[j].id];
101	          dx = a.x - b.x; dy = a.y - b.y;
102	          d2 = dx * dx + dy * dy; if (d2 < 4) d2 = 4;
103	          d = Math.sqrt(d2);
104	          f = 34000 / d2;
105	          dx /= d; dy /= d;
106	          a.vx += dx * f; a.vy += dy * f;
107	          b.vx -= dx * f; b.vy -= dy * f;
108	        }
109	      }
110	      // 边弹簧
111	      edges.forEach(function (e) {
112	        a = pos[e.s]; b = pos[e.t];
113	        dx = b.x - a.x; dy = b.y - a.y;
114	        d = Math.sqrt(dx * dx + dy * dy) || 1;
115	        f = (d - 128) * 0.024;
116	        dx /= d; dy /= d;
117	        a.vx += dx * f; a.vy += dy * f;
118	        b.vx -= dx * f; b.vy -= dy * f;
119	      });
120	      // 引力：全图中心 + 类型簇
121	      nodes.forEach(function (n) {
122	        var p = pos[n.id], c = CLUSTER[n.type];
123	        p.vx += (0 - p.x) * 0.003 + (c[0] - p.x) * 0.022;
124	        p.vy += (0 - p.y) * 0.003 + (c[1] - p.y) * 0.022;
125	      });
126	      // 积分
127	      nodes.forEach(function (n) {
128	        var p = pos[n.id];
129	        p.vx *= 0.8; p.vy *= 0.8;
130	        p.x += p.vx; p.y += p.vy;
131	      });
132	    }
133	    return pos;
134	  }
135	  var pos = computeLayout();
136	
137	  // 适配 viewBox（整图恒在的关键：一次算好，永不裁剪）
138	  var PAD = 72;
139	  var minX = 1e9, minY = 1e9, maxX = -1e9, maxY = -1e9;
140	  nodes.forEach(function (n) {
141	    var p = pos[n.id];
142	    if (p.x < minX) minX = p.x; if (p.x > maxX) maxX = p.x;
143	    if (p.y < minY) minY = p.y; if (p.y > maxY) maxY = p.y;
144	  });
145	  var vb = { x: minX - PAD, y: minY - PAD, w: (maxX - minX) + PAD * 2, h: (maxY - minY) + PAD * 2 };
146	  var LABEL_BELOW = 20; // 标签在节点下方的余量
147	  vb.h += LABEL_BELOW;
148	
149	  var nodeR = {};
150	  nodes.forEach(function (n) {
151	    nodeR[n.id] = 6.5 + Math.sqrt(deg[n.id] || 1) * 2.05;
152	  });
153	
154	  /* ================= SVG 构建 ================= */
155	  var NS = 'http://www.w3.org/2000/svg';
156	  var svg = document.getElementById('graph');
157	  var gEdges = document.getElementById('edges');
158	  var gNodes = document.getElementById('nodes');
159	  svg.setAttribute('viewBox', vb.x + ' ' + vb.y + ' ' + vb.w + ' ' + vb.h);
160	
161	  function el(name, attrs) {
162	    var e = document.createElementNS(NS, name);
163	    for (var k in attrs) e.setAttribute(k, attrs[k]);
164	    return e;
165	  }
166	
167	  // 边（在依赖方向上略收边，给箭头留位）
168	  var edgeEls = [];
169	  edges.forEach(function (e, idx) {
170	    var a = pos[e.s], b = pos[e.t];
171	    var dx = b.x - a.x, dy = b.y - a.y;
172	    var d = Math.sqrt(dx * dx + dy * dy) || 1;
173	    var ux = dx / d, uy = dy / d;
174	    var x1 = a.x + ux * (nodeR[e.s] + 2), y1 = a.y + uy * (nodeR[e.s] + 2);
175	    var x2 = b.x - ux * (nodeR[e.t] + 5.5), y2 = b.y - uy * (nodeR[e.t] + 5.5);
176	    var km = KIND_META[e.kind];
177	    var line = el('line', {
178	      x1: x1, y1: y1, x2: x2, y2: y2,
179	      stroke: km.color, 'class': 'edge'
180	    });
181	    if (km.dash) line.setAttribute('stroke-dasharray', km.dash);
182	    line.dataset.s = e.s; line.dataset.t = e.t;
183	    line.dataset.marker = 'url(#' + km.marker + ')';
184	    line.setAttribute('marker-end', line.dataset.marker);
185	    var ti = el('title', {});
186	    ti.textContent = byId[e.s].name + ' —' + km.label + '→ ' + byId[e.t].name;
187	    line.appendChild(ti);
188	    gEdges.appendChild(line);
189	    edgeEls.push(line);
190	  });
191	
192	  // 节点
193	  var nodeEls = new Map();
194	  nodes.forEach(function (n) {
195	    var p = pos[n.id];
196	    var r = nodeR[n.id];
197	    var g = el('g', { 'class': 'node', transform: 'translate(' + p.x + ',' + p.y + ')' });
198	    g.appendChild(el('circle', { 'class': 'halo halo-imp', r: r + 11 }));
199	    g.appendChild(el('circle', { 'class': 'halo halo-dep', r: r + 6 }));
200	    g.appendChild(el('circle', { 'class': 'focusring', r: r + 3 }));
201	    var tm = TYPE_META[n.type];
202	    var c = el('circle', {
203	      'class': 'main', r: r,
204	      fill: tm.color, 'fill-opacity': .16,
205	      stroke: tm.color, 'stroke-width': 2
206	    });
207	    g.appendChild(c);
208	    var t = el('text', { 'class': 'label', y: r + 15 });
209	    t.textContent = n.name;
210	    g.appendChild(t);
211	    g.dataset.id = n.id;
212	    gNodes.appendChild(g);
213	    nodeEls.set(n.id, g);
214	  });
215	
216	  /* ================= 状态 ================= */
217	  var state = {
218	    focus: 'order',          // 首屏默认焦点：订单服务
219	    trail: ['order'],
220	    radius: 1,
221	    hiddenTypes: new Set(),
222	    p0Only: false
223	  };
224	  var currentH = null; // {st, dep, imp}
225	
226	  function radiusLabel() {
227	    return state.radius >= 99 ? '全部' : state.radius + ' 跳';
228	  }
229	
230	  /* ================= 高亮刷新 ================= */
231	  function refresh() {
232	    var H = null, dep = null, imp = null;
233	    if (state.focus) {
234	      dep = bfsDepth(state.focus, outAdj);
235	      imp = bfsDepth(state.focus, inAdj);
236	    }
237	    var R = state.radius;
238	    var st = {};
239	    nodes.forEach(function (n) {
240	      var gd = dep && dep.get(n.id), gi = imp && imp.get(n.id);
241	      st[n.id] = {
242	        d: (gd !== undefined && gd <= R) ? gd : Infinity,
243	        i: (gi !== undefined && gi <= R) ? gi : Infinity,
244	        hidden: state.hiddenTypes.has(n.type) || (state.p0Only && n.crit !== 'P0')
245	      };
246	    });
247	
248	    // 跟随路径上的边
249	    var trailPair = new Set();
250	    for (var i = 0; i + 1 < state.trail.length; i++) {
251	      trailPair.add(state.trail[i] + '|' + state.trail[i + 1]);
252	    }
253	
254	    nodeEls.forEach(function (g, id) {
255	      var s = st[id];
256	      g.classList.toggle('off', s.hidden);
257	      g.classList.toggle('dim', !s.hidden && !!state.focus && s.d === Infinity && s.i === Infinity);
258	      g.classList.toggle('focus', state.focus === id);
259	      g.classList.toggle('dep', s.d < Infinity && state.focus !== id);
260	      g.classList.toggle('imp', s.i < Infinity && state.focus !== id);
261	      var hd = g.querySelector('.halo-dep'), hi = g.querySelector('.halo-imp');
262	      hd.style.opacity = (state.focus && s.d > 0 && s.d < Infinity) ? Math.max(.28, .95 - s.d * .2) : 0;
263	      hi.style.opacity = (state.focus && s.i > 0 && s.i < Infinity) ? Math.max(.28, .95 - s.i * .2) : 0;
264	      hd.style.transitionDelay = (s.d < Infinity ? s.d * 70 : 0) + 'ms';
265	      hi.style.transitionDelay = (s.i < Infinity ? s.i * 70 : 0) + 'ms';
266	    });
267	
268	    edgeEls.forEach(function (L) {
269	      var s = st[L.dataset.s], t = st[L.dataset.t];
270	      var hidden = s.hidden || t.hidden;
271	      L.classList.toggle('hidden', hidden);
272	      var trail = trailPair.has(L.dataset.s + '|' + L.dataset.t) || trailPair.has(L.dataset.t + '|' + L.dataset.s);
273	      var lit = !!state.focus && ((s.d < Infinity || s.i < Infinity) && (t.d < Infinity || t.i < Infinity));
274	      L.classList.toggle('trail', trail);
275	      L.classList.toggle('lit', lit && !trail);
276	      L.classList.toggle('dim', !!state.focus && !lit && !trail);
277	      L.setAttribute('marker-end', trail ? 'url(#m-trail)' : L.dataset.marker);
278	    });
279	
280	    currentH = { st: st, dep: dep, imp: imp };
281	  }
282	
283	  /* ================= 面板 ================= */
284	  var panel = document.getElementById('panel');
285	
286	  function kindSummary(items) {
287	    var cnt = {};
288	    items.forEach(function (it) { cnt[it.kind] = (cnt[it.kind] || 0) + 1; });
289	    return Object.keys(cnt).map(function (k) { return KIND_META[k].tag + ' ' + cnt[k]; }).join(' · ');
290	  }
291	
292	  // 一跳关系（pub 视为相互依赖：主题的依赖里含发布方）
293	  function collectDeps(id) {
294	    var out = [];
295	    edges.forEach(function (e) {
296	      if (e.s === id) out.push({ id: e.t, kind: e.kind });
297	      if (e.kind === 'pub' && e.t === id) out.push({ id: e.s, kind: 'pub' });
298	    });
299	    return out;
300	  }
301	  function collectImps(id) {
302	    var out = [];
303	    edges.forEach(function (e) {
304	      if (e.t === id) out.push({ id: e.s, kind: e.kind });
305	    });
306	    return out;
307	  }
308	
309	  function relItemHTML(item, depth) {
310	    var n = byId[item.id];
311	    var tm = TYPE_META[n.type];
312	    var depDepth = (currentH.dep && currentH.dep.get(item.id));
313	    var depTxt = (depDepth !== undefined && depDepth > 0 && depDepth <= state.radius)
314	      ? '<span class="depth-chip">径 ' + depDepth + '</span>' : '';
315	    return '<button type="button" class="rel-item" data-id="' + n.id + '">' +
316	      '<span class="dot" style="background:' + tm.color + '"></span>' +
317	      '<span class="rel-name">' + n.name + '</span>' +
318	      (depth ? '<span class="depth-chip">' + depth + '跳</span>' : depTxt) +
319	      '<span class="rel-kind">' + KIND_META[item.kind].tag + '</span>' +
320	      '<span class="crit ' + n.crit + '">' + n.crit + '</span>' +
321	      '<span class="rel-go">›</span></button>';
322	  }
323	
324	  function groupedListHTML(items, depthMap) {
325	    if (!items.length) return '<div class="rel-none">（无）</div>';
326	    var byDepth = {};
327	    items.forEach(function (it) {
328	      var d = depthMap && depthMap.get(it.id);
329	      if (d === undefined || d > state.radius) d = 1;
330	      (byDepth[d] = byDepth[d] || []).push(it);
331	    });
332	    var html = '';
333	    Object.keys(byDepth).map(Number).sort(function (a, b) { return a - b; }).forEach(function (d) {
334	      if (Object.keys(byDepth).length > 1) {
335	        html += '<div class="rel-group">第 ' + d + ' 跳</div>';
336	      }
337	      byDepth[d].forEach(function (it) {
338	        html += relItemHTML(it, Object.keys(byDepth).length > 1 ? d : 0);
339	      });
340	    });
341	    return html;
342	  }
343	
344	  function renderPanel() {
345	    if (!state.focus) {
346	      panel.innerHTML =
347	        '<div class="p-empty"><span class="big">◍</span>' +
348	        '点击任意节点开始跟随<br>' +
349	        '<b style="color:#b9c4d2">蓝环</b> = 它依赖的上游 · <b style="color:#ffd4b3">橙环</b> = 依赖它的下游<br>' +
350	        '整图始终可见，跟随不会丢失全局上下文</div>';
351	      return;
352	    }
353	    var n = byId[state.focus];
354	    var tm = TYPE_META[n.type];
355	    var deps = collectDeps(n.id);
356	    var imps = collectImps(n.id);
357	
358	    var impCount = 0, impP0 = 0, depCount = 0;
359	    nodes.forEach(function (m) {
360	      if (m.id === n.id) return;
361	      var s = currentH.st[m.id];
362	      if (s.i < Infinity) { impCount++; if (m.crit === 'P0') impP0++; }
363	      if (s.d < Infinity) depCount++;
364	    });
365	
366	    panel.innerHTML =
367	      '<div class="p-head">' +
368	        '<span class="type-badge" style="--c:' + tm.color + '">' + tm.label + '</span>' +
369	        '<h2>' + n.name + ' <span class="crit ' + n.crit + '">' + n.crit + '</span></h2>' +
370	        '<div class="p-meta"><span>' + n.team + '</span><span class="sid">#' + n.id + '</span></div>' +
371	        '<p class="p-desc">' + n.desc + '</p>' +
372	      '</div>' +
373	      '<div class="p-narrative">若「<b>' + n.name + '</b>」不可用，' +
374	        '半径 <b>' + radiusLabel() + '</b> 内 <span class="n-imp">' + impCount + ' 个节点受影响</span>' +
375	        (impP0 ? '（含 P0 ×' + impP0 + '）' : '') +
