26	  };
27	  var KIND_META = {
28	    call: { label: '同步调用', tag: '调用', marker: 'm-call', color: '#4d6f96', dash: null },
29	    data: { label: '数据读写', tag: '读写', marker: 'm-data', color: '#2f8577', dash: null },
30	    pub:  { label: '发布事件', tag: '发布', marker: 'm-event', color: '#8d6fd6', dash: '6 3' },
31	    sub:  { label: '订阅事件', tag: '订阅', marker: 'm-event', color: '#8d6fd6', dash: '2 4' }
