36	  /* ================= 邻接与统计 ================= */
37	  // 语义：边 A→B = A 依赖 B；影响沿反向传播。pub（发布事件）为相互影响。
38	  var outAdj = new Map();  // a -> [b, ...]   a 依赖谁
39	  var inAdj = new Map();   // b -> [a, ...]   谁依赖 b（即 b 的影响对象）
40	  function pushAdj(m, a, b) {
41	    if (!m.has(a)) m.set(a, []);
42	    m.get(a).push(b);
43	  }
44	  var deg = {};
45	  edges.forEach(function (e) {
46	    pushAdj(outAdj, e.s, e.t);
47	    pushAdj(inAdj, e.t, e.s);
48	    if (e.kind === 'pub') { // 双向
49	      pushAdj(outAdj, e.t, e.s);
50	      pushAdj(inAdj, e.s, e.t);
51	    }
52	    deg[e.s] = (deg[e.s] || 0) + 1;
53	    deg[e.t] = (deg[e.t] || 0) + 1;
54	  });
55	
56	  function bfsDepth(start, adj) {
57	    var depth = new Map([[start, 0]]);
58	    var q = [start];
59	    while (q.length) {
60	      var cur = q.shift();
61	      var d = depth.get(cur);
62	      var nx = adj.get(cur) || [];
63	      for (var i = 0; i < nx.length; i++) {
64	        if (!depth.has(nx[i])) { depth.set(nx[i], d + 1); q.push(nx[i]); }
65	      }
66	    }
67	    return depth;
68	  }
69	
70	  /* ================= 确定性力导向布局 ================= */
71	  function mulberry32(seed) {
72	    return function () {
73	      seed |= 0; seed = seed + 0x6D2B79F5 | 0;
74	      var t = Math.imul(seed ^ seed >>> 15, 1 | seed);
75	      t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
76	      return ((t ^ t >>> 14) >>> 0) / 4294967296;
77	    };
78	  }
79	  // 类型簇中心（手排五角位，保证簇间分离、图面可读）
80	  var CLUSTER = {
81	    client:   [-460, -270],
82	    service:  [0, 0],
83	    queue:    [370, -230],
84	    data:     [380, 250],
85	    external: [-360, 280]
86	  };
87	  function computeLayout() {
88	    var rng = mulberry32(20260908);
89	    var pos = {};
90	    nodes.forEach(function (n) {
91	      var c = CLUSTER[n.type];
92	      pos[n.id] = { x: c[0] + (rng() - 0.5) * 300, y: c[1] + (rng() - 0.5) * 300, vx: 0, vy: 0 };
93	    });
94	    var ITER = 340;
95	    for (var it = 0; it < ITER; it++) {
96	      var i, j, a, b, dx, dy, d2, d, f;
97	      // 斥力
98	      for (i = 0; i < nodes.length; i++) {
99	        for (j = i + 1; j < nodes.length; j++) {
100	          a = pos[nodes[i].id]; b = pos[nodes[j].id];
101	          dx = a.x - b.x; dy = a.y - b.y;
102	          d2 = dx * dx + dy * dy; if (d2 < 4) d2 = 4;
103	          d = Math.sqrt(d2);
104	          f = 34000 / d2;
105	          dx /= d; dy /= d;
106	          a.vx += dx * f; a.vy += dy * f;
107	          b.vx -= dx * f; b.vy -= dy * f;
108	        }
109	      }
110	      // 边弹簧
111	      edges.forEach(function (e) {
112	        a = pos[e.s]; b = pos[e.t];
113	        dx = b.x - a.x; dy = b.y - a.y;
114	        d = Math.sqrt(dx * dx + dy * dy) || 1;
115	        f = (d - 128) * 0.024;
116	        dx /= d; dy /= d;
117	        a.vx += dx * f; a.vy += dy * f;
118	        b.vx -= dx * f; b.vy -= dy * f;
119	      });
120	      // 引力：全图中心 + 类型簇
121	      nodes.forEach(function (n) {
122	        var p = pos[n.id], c = CLUSTER[n.type];
123	        p.vx += (0 - p.x) * 0.003 + (c[0] - p.x) * 0.022;
124	        p.vy += (0 - p.y) * 0.003 + (c[1] - p.y) * 0.022;
125	      });
126	      // 积分
127	      nodes.forEach(function (n) {
128	        var p = pos[n.id];
129	        p.vx *= 0.8; p.vy *= 0.8;
130	        p.x += p.vx; p.y += p.vy;
131	      });
132	    }
133	    return pos;
134	  }
