362	<script>
363	// 星脉 · 服务关系图谱 — 内联数据集（电商平台核心交易链路）
364	// 节点: {id, name, type: service|data|queue|external|client, team, crit, desc}
365	// 边: [source, target, kind] — source 依赖 target，箭头指向被依赖方
366	//     kind: call 同步调用 | data 数据读写 | pub 发布事件(影响双向) | sub 订阅事件
367	window.GRAPH = (function () {
368	  var N = function (id, name, type, team, crit, desc) {
369	    return { id: id, name: name, type: type, team: team, crit: crit, desc: desc };
370	  };
371	
372	  var nodes = [
373	    // 客户端
374	    N('web', 'Web 商城', 'client', '前端', 'P1', 'PC / H5 下单入口'),
