1068	  /* ================= 启动 ================= */
1069	  // 深链：#focus=id & r=1|2|3|99 & trail=a,b,c（便于分享与自动化验证）
1070	  (function initFromHash() {
1071	    var h = location.hash.replace(/^#/, '');
1072	    if (!h) return;
1073	    h.split('&').forEach(function (kv) {
1074	      var p = kv.split('=');
1075	      var k = p[0], v = decodeURIComponent(p[1] || '');
1076	      if (k === 'focus' && byId[v]) { state.focus = v; state.trail = [v]; }
1077	      if (k === 'trail') {
1078	        var ids = v.split(',').filter(function (id) { return !!byId[id]; });
1079	        if (ids.length) { state.trail = ids; state.focus = ids[ids.length - 1]; }
1080	      }
1081	      if (k === 'r' && +v) state.radius = +v >= 99 ? 99 : Math.min(3, Math.max(1, +v));
1082	    });
1083	  })();
